window.DOSIK=window.DOSIK||{};DOSIK["jk_tax"]={"1":[{"t":"table","title":"조세의 성격","head":["항목","내용"],"rows":[["법인세","조세의 사용용도가 특정되지 않은 조세"],["부가가치세","납세의무자와 담세자가 다른 조세"],["농어촌특별세","다른 조세에 부가되는 조세"],["조세의 개념","조세의 과세요건은 반드시 법률로 규정해야 한다 · 조세는 금전납부가 원칙이나, 특수한 경우 물납을 허용하고 있다"],["공과금","공공단체가 공공사업에 필요한 경비에 충당하기 위하여 부과하는 공과금은 조세에 해당하지 않는다"]]},{"t":"table","title":"국세부과의 원칙","head":["원칙","내용"],"rows":[["신의성실의 원칙","납세자가 그 의무를 이행할 때 신의에 따라 성실하게 할 것을 요구하는 원칙으로, 세무공무원이 직무를 수행할 때에도 적용된다"],["근거과세의 원칙","국세를 조사·결정할 때, 장부의 기록내용이 사실과 다르거나 장부의 기록에 누락된 것이 있을 때에는 그 부분에 대해서만 과세관청이 조사한 사실에 따라 결정할 수 있다"],["실질과세원칙","실질과 다른 법형식을 통해 조세부담을 회피하는 행위를 방지하고 부담능력에 따른 과세를 실현하고자 하는 것"]]},{"t":"table","title":"불복절차","head":["절차","내용"],"rows":[["심사청구와 심판청구","국세기본법에 따른 동일한 처분에 대하여 심사청구와 심판청구를 중복하여 제기할 수 없다"],["행정소송","심판청구에 대한 결정통지를 받은 후 행정소송을 제기하려는 경우 심판청구에 대한 결정 통지를 받은 날부터 90일 이내에 제기하여야 한다"],["과세전적부심사","세무조사결과통지 또는 과세예고통지를 받은 자는 통지를 받은 날부터 30일 이내에 청구할 수 있다"]]}],"3":[{"t":"table","title":"소득세의 과세방식","head":["항목","내용"],"rows":[["누진과세","과세표준의 증가에 따라 세율이 증가하는 누진과세를 채택"],["분류과세","퇴직소득과 양도소득은 다른 소득과 합산하지 않고 별도로 과세한다"],["열거주의","원칙적으로 열거주의에 의해 과세대상소득을 규정하고 있으며 예외적으로 이자 및 배당 소득에 한하여 유형별 포괄주의를 채택"]]},{"t":"table","title":"소득의 수입시기","head":["소득","수입시기"],"rows":[["잉여금 처분에 의한 상여","당해 법인의 잉여금 처분 결의일"],["인정상여","근로를 제공한 날이 속하는 사업연도"],["주식매수선택권 행사로 인한 근로소득","주식매수선택권을 행사한 날"]]},{"t":"table","title":"원천징수와 확정신고","head":["항목","내용"],"rows":[["분리과세대상소득","원천징수로써 납세의무가 종결된다"],["비영업대금의 이익","원천징수세율은 25%"],["원천징수의 주체","세금을 실제로 부담하는 납세의무자와 이를 실제 신고 납부하는 원천징수의무자는 서로 다르다"],["확정신고 예","내국법인의 부장으로 근무하는 김삼일씨가 근로소득 총수입금액 1억원 외의 다른 소득이 없는 경우 종합소득세 확정신고를 안 해도 된다 · 국내은행에서 발생하는 정기예금이자 1,500만원 외의 다른 소득이 없는 거주자 김철수 할아버지는 종합소득세 확정신고를 안 해도 된다"],["사업장 현황신고","부가가치세 면세사업자의 총수입금액을 파악하기 위한 제도로써 다음연도 2월 10일까지 자진신고하여야 한다"]]}],"4":[{"t":"table","title":"사업연도","head":["항목","내용"],"rows":[["사업연도","법령이나 법인의 정관 등에서 정하는 1회계기간으로 하되 그 기간은 1년을 초과하지 못한다"],["규정이 없는 내국법인","따로 사업연도를 정하여 법인 설립신고 또는 사업자등록과 함께 납세지 관할 세무서장에게 사업연도를 신고하여야 하며, 신고하지 않은 경우에는 매년 1월 1일부터 12월 31일까지를 그 법인의 사업연도로 한다"],["사업연도 변경","변경하려는 법인은 그 법인의 직전 사업연도 종료일부터 3개월 이내에 납세지 관할 세무서장에게 이를 신고하여야 한다"]]},{"t":"table","title":"손금·자본적 지출·상각","head":["항목","내용"],"rows":[["손금항목","계약상 의무불이행으로 인한 지체상금은 손금항목"],["업무무관자산","법인의 업무에 직접 사용하지 않는 부동산은 업무무관자산에 해당 · 업무무관부동산의 감가상각비는 손금불산입하여 유보로 소득처분한다"],["자본적 지출","건물에 엘리베이터를 설치한 비용은 자본적 지출에 해당 · 재해로 손실되어 자산의 본래용도에 이용할 가치가 없는 건축물 등의 복구비용은 자본적 지출에 해당"],["광업권의 상각","무신고시 생산량비례법을 적용한다"]]},{"t":"table","title":"세무조정 사례","head":["사례","세무조정"],"rows":[["사례 1","2025년: (손금산입) 1,000,000원 (△유보) · 2026년: (손금산입) 2,000,000원 (△유보)"],["사례 2","2025년: (손금불산입) 1,000,000원 (유보) · 2026년: 세무조정 없음"],["사례 3","2025년: (손금산입) 4,000,000원 (△유보) · 2026년: (손금산입) 2,000,000원 (△유보)"]]}],"5":[{"t":"table","title":"부가가치세의 특징","head":["항목","내용"],"rows":[["재화의 수입","수입자가 사업자인지 여부와 관계없이 부가가치세가 과세된다"],["세율","납세자의 소득수준과 관계없이 모두 동일한 세율이 적용된다"],["다단계과세","최종소비자에게 이르기까지 모든 거래단계에서 창출된 부가가치에 대하여 각 단계별로 과세하는 다단계과세방법에 따르고 있다"]]},{"t":"table","title":"과세기간","head":["대상","과세기간"],"rows":[["폐업자","폐업일이 속하는 과세기간 개시일부터 폐업일까지를 최종 과세기간으로 한다"],["간이과세자","과세기간을 1월 1일부터 12월 31일로 한다"],["일반과세자","1년을 2개의 과세기간으로 나누어, 매 6개월마다 확정신고 납부하도록 하고 있다"]]},{"t":"table","title":"사업장","head":["대상","사업장"],"rows":[["하치장","재화의 보관 관리 시설만을 갖춘 장소로서 사업자가 관할세무서장에게 그 설치신고를 한 하치장은 사업장이 아니다"],["무인자동판매기를 통한 사업","재화·용역을 공급하는 사업은 그 사업에 관한 업무총괄장소를 사업장으로 한다"],["부동산임대업","그 부동산의 등기부상의 소재지를 사업장으로 한다"]]},{"t":"table","title":"간주공급","head":["항목","내용"],"rows":[["개인적공급","간주공급 중 개인적공급에 해당할 경우 세금계산서 발급의무가 면제된다"],["견본품","사업을 위하여 무상으로 다른 사업자에게 인도 또는 양도하는 견본품은 사업상 증여에 해당하지 아니한다"],["면세전용","간주공급 중 면세전용의 공급시기는 재화를 사용하거나 소비하는 때이다"]]}]};
